import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const upstream = process.argv[2] && resolve(process.argv[2]);
if (!upstream) throw new Error('Provide the Reactive Resume source checkout directory.');
const commit = 'a2ad05181e133f4981fc1d8a2c46811069af4d25';
if (execFileSync('git', ['-C', upstream, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim() !== commit) {
  throw new Error('Use the Reactive Resume v6.1.1 checkout at ' + commit);
}

// Keep the default Reactive Resume families plus every script, punctuation, and legacy fallback family
// referenced by @reactive-resume/fonts. The plugin replaces rendered font-family rules with system fonts,
// so the ~1,400 decorative Google Fonts entries are unused at runtime.
const RETAINED_WEB_FONT_FAMILIES = new Set([
  'IBM Plex Sans',
  'IBM Plex Serif',
  'Noto Sans',
  'Noto Serif',
  'Noto Sans SC',
  'Noto Serif SC',
  'Noto Sans TC',
  'Noto Serif TC',
  'Noto Sans JP',
  'Noto Serif JP',
  'Noto Sans KR',
  'Noto Serif KR',
  'Noto Naskh Arabic',
  'Noto Sans Arabic',
  'Noto Sans Hebrew',
  'Noto Sans Thai',
  'Noto Sans Devanagari',
  'Noto Serif Bengali',
  'Noto Sans Bengali',
  'Noto Sans Gurmukhi',
  'Noto Sans Gujarati',
  'Noto Sans Oriya',
  'Noto Sans Tamil',
  'Noto Sans Telugu',
  'Noto Sans Kannada',
  'Noto Sans Malayalam',
  'Noto Sans Sinhala',
  'Noto Sans Ethiopic',
  'Noto Sans Khmer',
  'Noto Serif Georgian',
  'Noto Sans Georgian',
  'Noto Emoji',
  'Noto Sans Symbols',
  'Noto Sans Symbols 2',
  'ZCOOL QingKe HuangYou',
  'Arimo',
  'Tinos',
  'Carlito',
  'EB Garamond',
]);

const require = createRequire(import.meta.url);
const { build } = require(resolve(upstream, 'node_modules/.pnpm/esbuild@0.28.2/node_modules/esbuild'));
const pdf = resolve(upstream, 'packages/pdf');
const rendererOut = fileURLToPath(new URL('../../src/vendor/reactive-resume-renderer.mjs', import.meta.url));
const catalogOut = fileURLToPath(new URL('../../src/vendor/reactive-resume-templates.mjs', import.meta.url));

await build({
  stdin: {
    sourcefile: 'local-renderer.ts',
    resolveDir: pdf,
    loader: 'ts',
    contents: [
      "export { renderResumeWebPage } from './src/html/web-page.tsx';",
      "export { defaultResumeData, sectionDefaults } from '@reactive-resume/schema/resume/default';",
      "export { templateSchema, templateLayouts } from '@reactive-resume/schema/templates';",
    ].join('\n'),
  },
  outfile: rendererOut,
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  jsx: 'automatic',
  define: { 'process.env.NODE_ENV': '"production"' },
  plugins: [
    {
      // css-tree's ESM entry uses createRequire for data files. Its CommonJS entry
      // exposes those imports to esbuild, so its data travels with the bundle.
      name: 'bundle-css-tree-data',
      setup(context) {
        context.onResolve({ filter: /^css-tree$/ }, args => ({
          path: createRequire(args.importer).resolve(args.path),
        }));
      },
    },
    {
      // The plugin sets data.metadata.page.hideIcons = true and passes empty contact icons,
      // so the bundled Phosphor SVG icon tables (~784 KiB) are never drawn.
      name: 'trim-unused-phosphor-icons',
      setup(context) {
        context.onLoad({ filter: /packages[\\/]pdf[\\/]src[\\/]forme[\\/]phosphor-icons[\\/](?:common|rest)\.json$/ }, () => ({
          contents: '{}',
          loader: 'json',
        }));
      },
    },
    {
      // Trim the Google Fonts catalog to default + fallback families so local rendering stays
      // byte-for-byte identical while dropping ~470 KiB of unused font metadata.
      name: 'trim-unused-webfont-catalog',
      setup(context) {
        context.onLoad({ filter: /packages[\\/]fonts[\\/]src[\\/]webfontlist\.json$/ }, args => {
          const all = JSON.parse(readFileSync(args.path, 'utf8'));
          const kept = all.filter(font => RETAINED_WEB_FONT_FAMILIES.has(font?.family));
          return { contents: JSON.stringify(kept), loader: 'json' };
        });
      },
    },
  ],
  minify: true,
  legalComments: 'linked',
  banner: {
    js: '/* Reactive Resume v6.1.1. See reactive-resume-third-party-licenses.txt. */\n'
      + 'import { createRequire as createNodeRequire } from "node:module"; const require = createNodeRequire(import.meta.url);',
  },
});

// Generate a lightweight (~1.6 KiB) template catalog so host startup never has to eagerly load the full renderer.
const { templateSchema, templateLayouts } = await import(new URL('../../src/vendor/reactive-resume-renderer.mjs', import.meta.url).href + `?t=${Date.now()}`);
const catalogSource = [
  '/* Generated by vendor/reactive-resume-renderer/build.mjs from Reactive Resume v6.1.1 (@reactive-resume/schema/templates). */',
  `export const templateIds = Object.freeze(${JSON.stringify(templateSchema.options)});`,
  `export const templateLayouts = Object.freeze(${JSON.stringify(templateLayouts, null, 2)});`,
  '',
].join('\n');
await writeFile(catalogOut, catalogSource, 'utf8');
